/**
 *
 * TreeToggleIndicator displays a visual indicator for the expanded/collapsed state of a node.
 * Must be used inside `Tree.Toggle`. Uses the `match` prop for conditional visibility.
 *
 * [Live Demo](https://www.primereact.org/tree/)
 *
 * @module TreeToggleIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TreeRootInstance } from './TreeRoot.types';
/**
 * Defines passthrough(pt) options type in TreeToggleIndicator component.
 */
export type TreeToggleIndicatorPassThroughType<E> = PassThroughType<TreeToggleIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of TreeToggleIndicator component.
 */
export interface TreeToggleIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TreeToggleIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in TreeToggleIndicator component.
 */
export interface TreeToggleIndicatorProps extends BaseComponentProps<TreeToggleIndicatorInstance, unknown, TreeToggleIndicatorPassThrough, 'span'> {
    /**
     * Determines the visibility of the indicator based on the toggle state.
     * - "expanded": Visible when the node is expanded.
     * - "collapsed": Visible when the node is collapsed.
     * - "always": Indicator is always visible (useful for loading spinners).
     * @defaultValue 'always'
     */
    match?: 'expanded' | 'collapsed' | 'always' | undefined;
}
/**
 * Defines valid state in TreeToggleIndicator component.
 */
export interface TreeToggleIndicatorState {
}
/**
 * Defines the methods and properties exposed by TreeToggleIndicator component.
 */
export interface TreeToggleIndicatorExposes {
    /**
     * The Tree component instance.
     */
    tree: TreeRootInstance | undefined | null;
}
/**
 * Instance of TreeToggleIndicator component.
 */
export type TreeToggleIndicatorInstance = ComponentInstance<TreeToggleIndicatorProps, TreeToggleIndicatorState, TreeToggleIndicatorExposes>;
